import sys, heapq

def main():
    lines = sys.stdin.read().split()
    idx = 0
    slots = []  # list of dict: {'buf': bytearray, 'gen': int, 'occupied': bool}
    free_heap = []
    live_count = 0
    live_bytes = 0
    out = []

    def is_live(i, g):
        if i >= len(slots):
            return False
        s = slots[i]
        return s['occupied'] and s['gen'] == g

    while idx < len(lines):
        cmd = lines[idx]; idx += 1
        if cmd == 'new':
            s = int(lines[idx]); idx += 1
            if free_heap:
                slot = heapq.heappop(free_heap)
                slots[slot]['buf'] = bytearray(s)
                slots[slot]['gen'] += 1
                slots[slot]['occupied'] = True
            else:
                slot = len(slots)
                slots.append({'buf': bytearray(s), 'gen': 1, 'occupied': True})
            live_count += 1
            live_bytes += s
            out.append(f"h {slot} {slots[slot]['gen']}")
        elif cmd == 'set':
            i = int(lines[idx]); g = int(lines[idx+1]); off = int(lines[idx+2]); v = int(lines[idx+3]); idx += 4
            if not is_live(i, g):
                out.append("stale")
            elif off >= len(slots[i]['buf']):
                out.append("bounds")
            else:
                slots[i]['buf'][off] = v
                out.append("ok")
        elif cmd == 'sum':
            i = int(lines[idx]); g = int(lines[idx+1]); idx += 2
            if not is_live(i, g):
                out.append("stale")
            else:
                out.append(str(sum(slots[i]['buf'])))
        elif cmd == 'move':
            i = int(lines[idx]); g = int(lines[idx+1]); j = int(lines[idx+2]); h = int(lines[idx+3]); idx += 4
            if not is_live(i, g) or not is_live(j, h):
                out.append("stale")
            elif i == j and g == h:
                out.append("same")
            else:
                slots[j]['buf'].extend(slots[i]['buf'])
                slots[i]['occupied'] = False
                slots[i]['buf'] = bytearray(0)
                live_count -= 1
                heapq.heappush(free_heap, i)
                out.append(f"ok {len(slots[j]['buf'])}")
        elif cmd == 'free':
            i = int(lines[idx]); g = int(lines[idx+1]); idx += 2
            if not is_live(i, g):
                out.append("stale")
            else:
                live_count -= 1
                live_bytes -= len(slots[i]['buf'])
                slots[i]['occupied'] = False
                slots[i]['buf'] = bytearray(0)
                heapq.heappush(free_heap, i)
                out.append("ok")
        else:
            raise ValueError(f"unknown command {cmd}")

    out.append(f"live {live_count} {live_bytes}")
    print('\n'.join(out))

main()
